-- Replace only the generated introductions, preserving descriptions written by editors.
UPDATE `marker_category`
SET `description` = CASE
  WHEN name REGEXP 'Heart.*Piece|Piece.*Heart' THEN 'Collect four Pieces of Heart to add another heart to your health meter.'
  WHEN name = 'Heart Containers' THEN 'A little more health can make a big difference. Pick up these Heart Containers to extend your health meter.'
  WHEN name = 'Gold Skulltulas' THEN 'Listen for the scratching of a Gold Skulltula, then collect its token. Some only appear at night or during a particular age.'
  WHEN name = 'Big Poes' THEN 'Keep an eye out while riding through Hyrule Field. Defeat Big Poes and catch their spirits in a bottle.'
  WHEN name = 'Silver Rupees' THEN 'Gather the silver rupees in each puzzle to open the way forward.'
  WHEN name = 'Fairy Thoughts' THEN 'There are little traces of fairy thoughts waiting to be discovered. Check the locations below as you explore.'
  WHEN name = 'Ocarina Songs' THEN 'A familiar melody can open a path or carry you somewhere new. Here is where to learn each song.'
  WHEN name = 'Bottles' THEN 'An empty bottle always comes in handy. These are the rewards and encounters that can add one to your collection.'
  WHEN name LIKE '%Korok%' THEN 'Something look out of place? Solve the little puzzles hidden around the world to uncover Koroks and collect their seeds.'
  WHEN name LIKE '%Seashell%' THEN 'Secret Seashells are tucked away all over Koholint Island. Look closely, dig around, and keep track of the ones you have found.'
  WHEN name LIKE '%Might Crystal%' THEN 'Keep an eye out for Might Crystals as you explore. They are worth saving for upgrades.'
  WHEN name LIKE '%Stamp%' THEN 'Stop by these stamp stands and add another stamp to your collection.'
  WHEN name REGEXP 'Tears|Memories' THEN 'Piece together the story by visiting these places and uncovering their memories.'
  WHEN name REGEXP 'Treasure|Chest' THEN 'There is something worth opening here. Check the entries below to see what each chest holds.'
  WHEN name REGEXP 'Warp Pad|Waypoint' THEN 'Activate these travel points so you can return to them later.'
  WHEN name = 'Kaepora Gaebora' THEN 'The wise owl has a few things to tell you. Here is where you can meet him on your travels.'
  WHEN name REGEXP 'Tower' THEN 'These towers make useful landmarks and travel points. Visit them as you uncover more of Hyrule.'
  WHEN name REGEXP 'Shrine' THEN 'Step inside a shrine and take on its challenge. Use this list to keep track of the ones you have visited.'
  WHEN name = 'Lightroot' THEN 'Lightroots help you find your way through the Depths. Activate them to bring light to the surrounding darkness.'
  WHEN name REGEXP 'Dungeon Entrance|Dungeons|^Dungeon$|Divine Beast' THEN 'Ready for a bigger adventure? These entrances lead to some of the toughest puzzles and battles ahead.'
  WHEN name REGEXP 'Dungeon Map|^Map$' THEN 'A dungeon map makes it easier to get your bearings. Here is where to pick one up.'
  WHEN name REGEXP 'Compass' THEN 'Pick up a compass to help you keep track of important rooms and treasure inside a dungeon.'
  WHEN name REGEXP 'Boss Key' THEN 'You will need these keys before you can face the dungeon boss.'
  WHEN name REGEXP 'Key' THEN 'A locked door ahead? Check these key locations before retracing your steps.'
  WHEN name = 'Boss Doors' THEN 'Beyond these doors, a dungeon boss is waiting. Make sure you are ready before heading inside.'
  WHEN name REGEXP 'Fairy|Great Fairy' THEN 'Take a break and seek out a fairy. These places offer a welcome bit of help on your journey.'
  WHEN name REGEXP 'Shop|Business Scrub' THEN 'Running low on supplies? Visit these merchants and see what they have for sale.'
  WHEN name REGEXP 'NPC' THEN 'Meet the people who bring these places to life. Some have advice, requests, or rewards to share.'
  WHEN name REGEXP 'Gossip Stone' THEN 'These mysterious stones have things to say. Stop by and hear what they know.'
  WHEN name = 'Magic Bean Spots' THEN 'A patch of soft soil could be the start of a useful shortcut. Plant a Magic Bean and see what grows.'
  WHEN name = 'Cows' THEN 'These cows are worth a visit. You might even come away with something for an empty bottle.'
  WHEN name REGEXP 'Minigame' THEN 'Fancy a change of pace? Try these games and challenges, and see what you can win.'
  WHEN name REGEXP 'Capacity|Upgrade' THEN 'Make room for more supplies and improve your gear with these upgrades.'
  WHEN name = 'Spells' THEN 'Add a little magic to your adventure. These are the places to learn new spells.'
  WHEN name = 'Masks' THEN 'A different face can lead to a different conversation. Keep track of the masks you can collect here.'
  WHEN name REGEXP 'Weapon|Bow|Arrow|Shield|Armor|Equipment|Tools|Quest Items' THEN 'Need a new piece of gear? Check these locations for equipment and useful items to take on your travels.'
  WHEN name REGEXP 'Trading Sequence' THEN 'One good trade leads to another. Follow the trading sequence and keep track of who needs your next item.'
  WHEN name REGEXP 'Side.?Quest' THEN 'There is more to do than follow the main story. Meet people, lend a hand, and see where these side quests take you.'
  WHEN name = 'Cracked Walls' THEN 'That wall looks a little suspicious. Bring something that can break it open and see what is hidden behind it.'
  WHEN name REGEXP 'Village|House|Stable' THEN 'Stop in, look around, and meet the locals. These places are useful stops along the way.'
  WHEN name REGEXP 'Cooking Pot' THEN 'Turn your ingredients into something useful at one of these cooking pots.'
  WHEN name REGEXP 'Goddess Statue' THEN 'Take a moment to pray at a Goddess Statue and put your blessings to use.'
  WHEN name REGEXP 'Diary|Book|Tablet' THEN 'There is a story to read here. Look through these writings as you explore.'
  WHEN name REGEXP 'Well|Cave|Chasm' THEN 'There is more to explore beneath the surface. Check these openings for a way in.'
  WHEN name = 'Device Dispenser' THEN 'Stock up on Zonai devices at these dispensers before setting out on your next build.'
  WHEN name = 'Sign Guy' THEN 'Addison could use a hand keeping those signs upright. Bring a little ingenuity along.'
  WHEN name = 'Cherry Tree' THEN 'These cherry trees make peaceful landmarks. Try leaving an offering and see what happens.'
  WHEN name = 'Forge Construct' THEN 'Visit these constructs when you are ready to trade for more Zonai supplies.'
  WHEN name = 'Bargainer Statue' THEN 'Have some Poes to spare? These statues may have something you want in exchange.'
  WHEN name = 'Dragon' THEN 'Watch the skies and follow these dragons as they travel through Hyrule.'
  WHEN name = 'Blupee' THEN 'A flash of blue in the distance may be a Blupee. Keep an eye on where it goes.'
  WHEN name = 'Ghost with Weapon' THEN 'These shadowy figures hold weapons you can take. It is worth checking on them while exploring the Depths.'
  WHEN name = 'Rock Octorok (Repair)' THEN 'A Rock Octorok can give worn gear a second chance. Visit these spots when your equipment needs attention.'
  WHEN name = 'Bubbulfrog' THEN 'Listen carefully while exploring caves. A Bubbulfrog may be hiding nearby.'
  WHEN name REGEXP 'Boss|Enemy|Guardian|Wizzrobe|Lynel|Talus|Hinox|Molduga|Gleeok|Flux Construct|Frox|Gloom Spawn' THEN 'Looking for a fight? Check these encounters and come prepared for the enemies waiting there.'
  WHEN name REGEXP 'Echo' THEN 'There is always something new to learn. Visit these places to add more echoes to your collection.'
  ELSE CONCAT('Keep track of ', name, ' as you explore. Select an entry below for a closer look.')
END
WHERE marker_category_type_id = 1
AND (description IS NULL OR description = '' OR description LIKE 'Find % locations in The Legend of Zelda: %. Explore the interactive map, view location details, and track your completion.');
